insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Supervisor de Taller', 'Dirige y supervisa las operaciones del taller de instalaciones, organizando el inicio y la distribución de los trabajos, controlando al personal, los tiempos, los inventarios, las herramientas, la maquinaria, los gastos y la caja chica, y verificando la calidad de los trabajos ejecutados, para asegurar entregas oportunas, un ambiente de trabajo ordenado y la reducción de reclamos de los clientes.', 'Graduado de nivel diversificado como Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. 2 años en puesto similar. Liderazgo, planificación, organización, comunicación efectiva, manejo de conflictos.', 'ACCISA-010', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Administrativo/Operativo', 'Q Base + Bonificación', $json${"no_supervisa": "11", "posiciones_supervisa": "Mecánicos Instaladores", "funciones": [{"categoria": "Planeación y Asignación del Trabajo", "funcion": "Ordenar el inicio de las labores del taller y establecer la forma de proceder para los trabajos correspondientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planeación y Asignación del Trabajo", "funcion": "Definir la secuencia y programación de los trabajos considerando las prioridades, fechas de entrega, carga de trabajo y capacidad técnica del personal.", "frecuencia": "", "tiempo": ""}, {"categoria": "Planeación y Asignación del Trabajo", "funcion": "Asignar los trabajos de manera equitativa y organizar los tiempos de descanso pactados por la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Supervisar el trabajo del personal del taller y verificar el cumplimiento de las actividades asignadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Controlar la asistencia, las horas extraordinarias y demás conceptos relacionados con el tiempo laborado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Mantener el archivo del personal a su cargo y registrar rendimiento, ausencias e irregularidades de comportamiento.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión del Personal y Desempeño", "funcion": "Promover la cordialidad, la cooperación y el trato respetuoso dentro del equipo, y brindar retroalimentación ante deficiencias de desempeño.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Velar por la calidad del trabajo realizado por el personal del taller para minimizar reclamos de clientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Inspeccionar los trabajos terminados y verificar su funcionamiento y conformidad antes de autorizar la entrega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Entregas y Servicio", "funcion": "Ajustar la operación a las fechas y horarios requeridos para la calendarización y entrega de trabajos terminados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Identificar necesidades de materiales, herramientas, equipos o repuestos y gestionar oportunamente su requerimiento con el área correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Controlar los inventarios de herramientas y equipos asignados al taller y a cada trabajador.", "frecuencia": "", "tiempo": ""}, {"categoria": "Inventarios, Equipos y Condiciones del Taller", "funcion": "Revisar el estado de las herramientas, equipos y áreas de trabajo y coordinar las acciones de mantenimiento o corrección necesarias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Informar al Supervisor de Ventas y Taller cualquier anomalía, novedad o situación relevante dentro del área a su cargo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Controlar los gastos ejecutados en el taller y administrar la caja chica para cubrir gastos del giro diario autorizados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Administrativo, Gastos y Reportes", "funcion": "Llevar el control de caja chica y presentar la documentación y los reportes correspondientes al Gerente Administrativo para revisión y aprobación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Vigilar las condiciones de seguridad del taller, el uso adecuado de herramientas y equipos y el cumplimiento de los procedimientos aplicables.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Coordinar o brindar inducción y capacitación sobre procedimientos de instalación, uso de equipos, calidad y prácticas seguras, y reportar los incidentes ocurridos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Seguridad, Capacitación y Mejora", "funcion": "Proponer mejoras en la organización del trabajo, calidad, productividad, uso de recursos y prevención de reclamos, y cumplir las demás atribuciones delegadas por el jefe inmediato.", "frecuencia": "", "tiempo": ""}, {"categoria": "Otros", "funcion": "Brindar apoyo operativo al equipo técnico cuando la carga de trabajo o las necesidades del servicio lo requieran, participando directamente en la instalación de accesorios, reparaciones o trabajos pendientes.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad: Alta. El puesto combina la planificación diaria del taller, asignación de trabajos, supervisión del personal, control de asistencia y horas extraordinarias, cumplimiento de fechas de entrega, verificación de calidad, control de inventarios, herramientas, maquinaria, gastos y caja chica.", "nivel_iniciativa": "Iniciativa: Media-Alta. Cuenta con autonomía operativa para asignar tareas, ordenar la secuencia del trabajo, coordinar descansos, verificar la calidad y detener actividades que presenten riesgos o incumplimientos. Los gastos no previstos, sanciones laborales, compras relevantes y decisiones que comprometan recursos o condiciones de entrega deben escalarse al Gerente Administrativo.", "manejo_activos": "Inventario del taller; herramientas, equipos y maquinaria asignados al área y a cada trabajador; caja chica y documentación de gastos; registros de asistencia, horas extraordinarias, desempeño y novedades del personal; órdenes de trabajo, programación de entregas y vehículos o accesorios bajo responsabilidad del taller durante la instalación.", "equipos_trabajo": "Uniforme corporativo y gafete; computadora; impresora; formatos o sistema para órdenes de trabajo, inventarios y reportes; herramientas de inspección y medición; acceso a maquinaria y equipos del taller según autorización.", "equipos_seguridad": "Calzado de seguridad, lentes de protección y guantes adecuados al trabajo. Protección respiratoria y auditiva cuando se realicen actividades de lijado, pintura o uso de herramientas que generen polvo o ruido.", "condiciones_trabajo": "El puesto se desarrolla principalmente en el taller de instalaciones, combinando actividades de supervisión en piso con tareas administrativas y de control. Requiere movilizarse constantemente entre las áreas de trabajo, revisar instalaciones, herramientas, equipos e inventarios, atender al personal y coordinar con Gerencia, Ventas y Bodega.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Medio-Alto. El puesto requiere alternar períodos de trabajo administrativo con recorridos frecuentes por el taller, permanecer de pie, inspeccionar trabajos dentro y alrededor de vehículos, revisar herramientas, equipos e inventarios y, cuando sea necesario, apoyar o demostrar procedimientos técnicos.\nNivel de esfuerzo mental: Alto. Requiere concentración, criterio técnico y capacidad para coordinar simultáneamente personal, trabajos, fechas de entrega, calidad, inventarios, gastos, caja chica y novedades laborales.", "perfil": {"edad": "35+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado como Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. Estudios universitarios en administración, ingeniería o gestión de operaciones son deseables, no indispensables.", "formacion_complementaria": "Cursos o diplomados en supervisión y liderazgo, planificación de talleres, control de calidad, manejo de inventarios, administración de caja chica, Excel y gestión de indicadores.", "conocimientos_basicos": "Mecánica y electricidad automotriz básica; instalación y conexión de accesorios.", "habilidades_especificas": "Liderazgo, planificación, organización, asignación equitativa del trabajo, comunicación efectiva, manejo de conflictos, retroalimentación, resolución de problemas, atención al detalle, orientación a resultados, trabajo bajo presión y servicio al cliente interno y externo.", "conocimientos_informaticos": "Microsoft Excel intermedio, Word, correo corporativo, Google Drive u OneDrive y herramientas digitales para reportes, asistencia, programación e inventarios.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente, según las necesidades de supervisión de instalaciones externas.", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, respeto, imparcialidad, compromiso, disciplina, orden, prudencia y orientación a la calidad.", "otros": "Disponibilidad para adaptar horarios a la programación de entregas terminadas y atender situaciones operativas extraordinarias."}, "competencias_generales": [{"competencia": "Responsabilidad", "grado": "A"}, {"competencia": "Planificación y organización", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Liderazgo", "grado": "A"}, {"competencia": "Toma de decisiones", "grado": "B"}], "competencias_especificas": [{"competencia": "Instalación de accesorios", "grado": "A"}, {"competencia": "Inspección y cuidado del vehículo", "grado": "A"}, {"competencia": "Control de calidad", "grado": "A"}, {"competencia": "Gestión de personal", "grado": "A"}, {"competencia": "Uso seguro de herramientas", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-010"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
