insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Encargado de Bodega', 'Administra y controla la mercadería asignada a la bodega del taller, asegurando su correcta recepción, clasificación, almacenamiento, registro y despacho contra la documentación autorizada, así como el orden de las existencias en bodega, sala de ventas y puntos de exhibición, para mantener información confiable y disponibilidad oportuna de los productos requeridos por Taller y Ventas.', 'Graduado de nivel diversificado como Perito Contador, Perito en Administración, Bachiller en Computación o carrera afín. 2 años en puesto similar. Organización, atención al detalle, habilidad numérica, integridad.', 'ACCISA-010', 'ACCISA', 'Operativo', 'Operativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Operativo', 'Q Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Recepción y Validación de Mercadería", "funcion": "Recibir la mercadería destinada a la bodega y comprobar que cuente con la documentación correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Recepción y Validación de Mercadería", "funcion": "Verificar la cantidad y condición de la mercadería recibida contra facturas, órdenes, traslados u otros documentos disponibles, y reportar diferencias o daños.", "frecuencia": "", "tiempo": ""}, {"categoria": "Recepción y Validación de Mercadería", "funcion": "Registrar documentalmente el ingreso de la mercadería y ubicarla en el espacio asignado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Entregar la mercadería solicitada por Taller o Ventas únicamente contra una orden de despacho o una factura debidamente pagada.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Despachar los productos requeridos cumpliendo las normas y controles establecidos para la salida de mercadería.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Registrar documentalmente cada egreso de mercadería y conservar el respaldo correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Despacho y Entrega Controlada", "funcion": "Verificar que el producto, cantidad y documento de entrega coincidan antes de completar el despacho.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Mantener un expediente y control estricto de todas las existencias, ingresos y egresos de mercadería.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Realizar arqueos selectivos o aleatorios de la mercadería en las bodegas centrales cuando lo considere oportuno.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Documental e Inventarios", "funcion": "Investigar y reportar las diferencias detectadas entre las existencias físicas y los registros, sin efectuar ajustes no autorizados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Ordenar y colocar la mercadería de forma clasificada dentro de la bodega y en la sala de ventas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Mantener el orden y la limpieza de las áreas de bodega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Clasificación y Exhibición", "funcion": "Controlar las mercaderías en exhibición en los puntos de venta establecidos mediante convenios especiales.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Informar al Gerente de Ventas y al Gerente Financiero los saldos, requerimientos y necesidades de importación de los productos a su cargo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Informar al Gerente de Ventas sobre la rotación de los productos para apoyar la definición de políticas de venta.", "frecuencia": "", "tiempo": ""}, {"categoria": "Saldos, Abastecimiento y Rotación", "funcion": "Cumplir las demás atribuciones delegadas por el jefe inmediato que sean necesarias para el cumplimiento del puesto.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad: Media-Alta. El puesto combina la recepción y entrega de mercadería, el control documental de ingresos y egresos, la clasificación física de productos, la realización de arqueos selectivos, la vigilancia de existencias en bodega y exhibiciones, y el reporte de saldos, rotación, faltantes y requerimientos de importación.", "nivel_iniciativa": "Iniciativa: Media-Alta. Cuenta con autonomía operativa para ordenar la bodega, verificar la documentación y ejecutar despachos debidamente autorizados.", "manejo_activos": "Mercadería almacenada en la bodega del taller y bodega central; productos ubicados en sala de ventas y puntos de exhibición por convenios especiales; documentos de ingreso y egreso, órdenes de despacho, facturas pagadas, expedientes de existencias, reportes de saldos, rotación, faltantes y requerimientos de importación.", "equipos_trabajo": "Uniforme corporativo y gafete; computadora, impresora, calculadora, formatos de control o acceso al sistema.", "equipos_seguridad": "Calzado de seguridad y guantes adecuados para la manipulación de mercadería; chaleco reflectivo cuando exista circulación de vehículos o equipos de manejo de materiales.", "condiciones_trabajo": "El puesto se desarrolla principalmente en bodegas, áreas de almacenamiento, sala de ventas y puntos de exhibición asignados. Combina trabajo documental y uso de sistemas con recorridos frecuentes, recepción, clasificación, conteo y entrega de mercadería.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Alto. El puesto requiere permanecer de pie durante parte importante de la jornada, caminar dentro de las áreas de bodega, agacharse, inclinarse, alcanzar estanterías y manipular, ordenar o trasladar mercadería.\nNivel de esfuerzo mental: Alto. Requiere concentración y atención al detalle para comparar documentos, verificar cantidades, registrar movimientos, mantener el control de las existencias, realizar conteos, identificar diferencias y reportar saldos, rotación, faltantes y requerimientos sin afectar la continuidad del Taller y Ventas.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado como Perito Contador, Perito en Administración, Bachiller en Computación o carrera afín.", "formacion_complementaria": "Cursos en manejo de inventarios, recepción y despacho, Excel, seguridad en bodegas, manipulación manual de materiales, orden y limpieza o metodología 5S.", "conocimientos_basicos": "Recepción y despacho de mercadería; revisión de órdenes, facturas y traslados; control de ingresos y egresos.", "habilidades_especificas": "Organización, atención al detalle, habilidad numérica, seguimiento, comunicación efectiva, integridad, orientación al servicio interno, capacidad para identificar diferencias, orden, disciplina y cuidado de la mercadería.", "conocimientos_informaticos": "Microsoft Excel intermedio, Word y herramientas digitales para reportes, programación e inventarios.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente, según las necesidades de supervisión de instalaciones externas.", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, respeto, imparcialidad, compromiso, disciplina, orden, prudencia y orientación a la calidad.", "otros": "Disponibilidad para realizar conteos, cierres o verificaciones extraordinarias cuando sean programadas y autorizadas."}, "competencias_generales": [{"competencia": "Organización y control", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Responsabilidad", "grado": "A"}], "competencias_especificas": [{"competencia": "Gestión de inventarios", "grado": "A"}, {"competencia": "Recepción y despacho", "grado": "A"}, {"competencia": "Conteos y arqueos", "grado": "A"}, {"competencia": "Análisis de rotación y faltantes", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-010 (Bodega)"}$json$::jsonb)
on conflict (puesto) do update set
